select current_timestamp as measured_at,(select jsonb_agg(jsonb_build_object('version',version,'name',name)) from supabase_migrations.schema_migrations where version='20260912140550') as ledger,(select jsonb_agg(jsonb_build_object('role',r.code,'effect',rp.effect,'status',rp.status,'revoked',rp.revoked_at is not null)) from public.institution_role_permissions rp join public.institution_roles r on r.id=rp.role_id join public.institution_permissions p on p.id=rp.permission_id where r.institution_id is null and r.is_system and r.code in ('institution_admin','institution_reader') and p.code='moments.publications.remove') as grants,position('has_institution_permission' in pg_get_functiondef('public.list_visible_moments(uuid,uuid,uuid,integer,timestamptz)'::regprocedure))>0 as truthful_hint,has_function_privilege('authenticated','public.list_visible_moments(uuid,uuid,uuid,integer,timestamptz)','EXECUTE') as authenticated,has_function_privilege('anon','public.list_visible_moments(uuid,uuid,uuid,integer,timestamptz)','EXECUTE') as anon;
